CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "first_name" varchar not null, "last_name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "location" varchar, "gender" varchar check ("gender" in ('male', 'female', 'other', 'prefer_not_to_say')), "date_of_birth" date, "bio" text, "phone" varchar, "profile_picture" varchar, "is_active" tinyint(1) not null default '1', "last_login_at" datetime, "email_verification_token" varchar, "email_verification_sent_at" datetime, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "address" varchar, "city" varchar, "state" varchar, "postal_code" varchar, "country" varchar, "latitude" numeric, "longitude" numeric, "community_name" varchar, "borough" varchar, "location_verified" tinyint(1) not null default '0', "is_online" tinyint(1) not null default '0', "last_seen_at" datetime, "radius" integer not null default '5', "main_goal" text, "auth_provider" varchar, "auth_provider_id" varchar, "allow_notifications" tinyint(1) not null default '0');
CREATE INDEX "users_email_is_active_index" on "users" ("email", "is_active");
CREATE INDEX "users_email_verification_token_index" on "users" ("email_verification_token");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE TABLE IF NOT EXISTS "oauth_auth_codes" ("id" varchar not null, "user_id" integer not null, "client_id" varchar not null, "scopes" text, "revoked" tinyint(1) not null, "expires_at" datetime, primary key ("id"));
CREATE INDEX "oauth_auth_codes_user_id_index" on "oauth_auth_codes" ("user_id");
CREATE TABLE IF NOT EXISTS "oauth_access_tokens" ("id" varchar not null, "user_id" integer, "client_id" varchar not null, "name" varchar, "scopes" text, "revoked" tinyint(1) not null, "created_at" datetime, "updated_at" datetime, "expires_at" datetime, primary key ("id"));
CREATE INDEX "oauth_access_tokens_user_id_index" on "oauth_access_tokens" ("user_id");
CREATE TABLE IF NOT EXISTS "oauth_refresh_tokens" ("id" varchar not null, "access_token_id" varchar not null, "revoked" tinyint(1) not null, "expires_at" datetime, primary key ("id"));
CREATE INDEX "oauth_refresh_tokens_access_token_id_index" on "oauth_refresh_tokens" ("access_token_id");
CREATE TABLE IF NOT EXISTS "oauth_clients" ("id" varchar not null, "owner_type" varchar, "owner_id" integer, "name" varchar not null, "secret" varchar, "provider" varchar, "redirect_uris" text not null, "grant_types" text not null, "revoked" tinyint(1) not null, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE INDEX "oauth_clients_owner_type_owner_id_index" on "oauth_clients" ("owner_type", "owner_id");
CREATE TABLE IF NOT EXISTS "oauth_device_codes" ("id" varchar not null, "user_id" integer, "client_id" varchar not null, "user_code" varchar not null, "scopes" text not null, "revoked" tinyint(1) not null, "user_approved_at" datetime, "last_polled_at" datetime, "expires_at" datetime, primary key ("id"));
CREATE INDEX "oauth_device_codes_user_id_index" on "oauth_device_codes" ("user_id");
CREATE INDEX "oauth_device_codes_client_id_index" on "oauth_device_codes" ("client_id");
CREATE UNIQUE INDEX "oauth_device_codes_user_code_unique" on "oauth_device_codes" ("user_code");
CREATE TABLE IF NOT EXISTS "comments" ("id" integer primary key autoincrement not null, "user_id" integer not null, "discussion_id" integer not null, "body" text not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("discussion_id") references "discussions"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "likes" ("id" integer primary key autoincrement not null, "user_id" integer not null, "likeable_type" varchar not null, "likeable_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE INDEX "likes_likeable_type_likeable_id_index" on "likes" ("likeable_type", "likeable_id");
CREATE TABLE IF NOT EXISTS "games" ("id" integer primary key autoincrement not null, "user_id" integer not null, "title" varchar not null, "location" varchar not null, "date" datetime not null, "venue_booked" tinyint(1) not null default '0', "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "game_user" ("id" integer primary key autoincrement not null, "user_id" integer not null, "game_id" integer not null, foreign key("user_id") references "users"("id") on delete cascade, foreign key("game_id") references "games"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "game_types" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "icon_path" varchar, "created_at" datetime, "updated_at" datetime, "color" varchar not null default '#3B82F6');
CREATE UNIQUE INDEX "game_types_name_unique" on "game_types" ("name");
CREATE TABLE IF NOT EXISTS "game_event_participants" ("id" integer primary key autoincrement not null, "game_event_id" integer not null, "user_id" integer not null, "is_waiting" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("game_event_id") references "game_events"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "game_user_interest" ("id" integer primary key autoincrement not null, "user_id" integer not null, "game_type_id" integer not null, "skill_level" integer not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("game_type_id") references "game_types"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "communities" ("id" integer primary key autoincrement not null, "name" varchar not null, "type" varchar not null default 'borough', "city" varchar not null, "state" varchar not null, "country" varchar not null, "latitude" numeric, "longitude" numeric, "description" text, "image_url" varchar, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "communities_name_city_state_country_unique" on "communities" ("name", "city", "state", "country");
CREATE INDEX "communities_city_state_country_index" on "communities" ("city", "state", "country");
CREATE INDEX "communities_latitude_longitude_index" on "communities" ("latitude", "longitude");
CREATE TABLE IF NOT EXISTS "user_communities" ("id" integer primary key autoincrement not null, "user_id" integer not null, "community_id" integer not null, "is_primary" tinyint(1) not null default '0', "is_active" tinyint(1) not null default '1', "joined_at" datetime not null default CURRENT_TIMESTAMP, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("community_id") references "communities"("id") on delete cascade);
CREATE UNIQUE INDEX "user_communities_user_id_community_id_unique" on "user_communities" ("user_id", "community_id");
CREATE INDEX "user_communities_user_id_is_primary_index" on "user_communities" ("user_id", "is_primary");
CREATE INDEX "users_city_state_country_index" on "users" ("city", "state", "country");
CREATE INDEX "users_community_name_borough_index" on "users" ("community_name", "borough");
CREATE INDEX "users_latitude_longitude_index" on "users" ("latitude", "longitude");
CREATE INDEX "users_location_verified_index" on "users" ("location_verified");
CREATE TABLE IF NOT EXISTS "game_events" ("id" integer primary key autoincrement not null, "game_type_id" integer not null, "organiser_id" integer not null, "skill_level" integer not null, "location" varchar not null, "starts_at" datetime not null, "venue_booked" tinyint(1) not null default ('0'), "max_participants" integer, "waiting_list_enabled" tinyint(1) not null default ('0'), "notes" text, "created_at" datetime, "updated_at" datetime, "address" varchar, "city" varchar, "state" varchar, "postal_code" varchar, "country" varchar, "latitude" numeric, "longitude" numeric, "community_name" varchar, "borough" varchar, "community_id" integer, foreign key("organiser_id") references users("id") on delete cascade on update no action, foreign key("game_type_id") references game_types("id") on delete cascade on update no action, foreign key("community_id") references "communities"("id") on delete set null);
CREATE INDEX "game_events_city_state_country_index" on "game_events" ("city", "state", "country");
CREATE INDEX "game_events_community_name_borough_index" on "game_events" ("community_name", "borough");
CREATE INDEX "game_events_latitude_longitude_index" on "game_events" ("latitude", "longitude");
CREATE INDEX "game_events_community_id_index" on "game_events" ("community_id");
CREATE TABLE IF NOT EXISTS "discussions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "title" varchar not null, "body" text not null, "created_at" datetime, "updated_at" datetime, "game_type_id" integer, game_event_id INTEGER NULL, foreign key("user_id") references users("id") on delete cascade on update no action, foreign key("game_type_id") references "game_types"("id") on delete set null);
CREATE INDEX "discussions_game_type_id_index" on "discussions" ("game_type_id");
CREATE TABLE IF NOT EXISTS "tournament_participants" ("id" integer primary key autoincrement not null, "tournament_id" integer not null, "user_id" integer not null, "registration_date" datetime not null, "payment_status" varchar check ("payment_status" in ('pending', 'paid', 'refunded')) not null default 'pending', "is_waiting" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("tournament_id") references "tournaments"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE UNIQUE INDEX "tournament_participants_tournament_id_user_id_unique" on "tournament_participants" ("tournament_id", "user_id");
CREATE INDEX "tournament_participants_tournament_id_payment_status_index" on "tournament_participants" ("tournament_id", "payment_status");
CREATE INDEX "tournament_participants_user_id_index" on "tournament_participants" ("user_id");
CREATE TABLE IF NOT EXISTS "tournament_brackets" ("id" integer primary key autoincrement not null, "tournament_id" integer not null, "name" varchar not null, "type" varchar not null default 'main', "round" integer not null default '1', "max_players" integer, "status" varchar check ("status" in ('pending', 'active', 'completed')) not null default 'pending', "created_at" datetime, "updated_at" datetime, foreign key("tournament_id") references "tournaments"("id") on delete cascade);
CREATE INDEX "tournament_brackets_tournament_id_round_index" on "tournament_brackets" ("tournament_id", "round");
CREATE INDEX "tournament_brackets_tournament_id_status_index" on "tournament_brackets" ("tournament_id", "status");
CREATE TABLE IF NOT EXISTS "tournament_matches" ("id" integer primary key autoincrement not null, "tournament_id" integer not null, "bracket_id" integer, "match_number" integer not null, "round" integer not null default '1', "player1_id" integer, "player2_id" integer, "winner_id" integer, "loser_id" integer, "scheduled_at" datetime, "started_at" datetime, "completed_at" datetime, "status" varchar check ("status" in ('scheduled', 'in-progress', 'completed', 'cancelled')) not null default 'scheduled', "score" text, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("tournament_id") references "tournaments"("id") on delete cascade, foreign key("bracket_id") references "tournament_brackets"("id") on delete cascade, foreign key("player1_id") references "users"("id") on delete set null, foreign key("player2_id") references "users"("id") on delete set null, foreign key("winner_id") references "users"("id") on delete set null, foreign key("loser_id") references "users"("id") on delete set null);
CREATE INDEX "tournament_matches_tournament_id_round_index" on "tournament_matches" ("tournament_id", "round");
CREATE INDEX "tournament_matches_tournament_id_status_index" on "tournament_matches" ("tournament_id", "status");
CREATE INDEX "tournament_matches_bracket_id_index" on "tournament_matches" ("bracket_id");
CREATE INDEX "tournament_matches_scheduled_at_index" on "tournament_matches" ("scheduled_at");
CREATE TABLE IF NOT EXISTS "tournaments" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "game_type_id" integer not null, "organiser_id" integer not null, "location" varchar not null, "address" varchar, "city" varchar, "state" varchar, "postal_code" varchar, "country" varchar, "latitude" numeric, "longitude" numeric, "starts_at" datetime not null, "ends_at" datetime not null, "registration_deadline" datetime not null, "max_participants" integer, "min_participants" integer not null default ('2'), "entry_fee" numeric not null default ('0'), "prize_pool" numeric, "prize_description" text, "skill_level" varchar not null default ('1'), "status" varchar not null default ('draft'), "is_featured" tinyint(1) not null default ('0'), "rules" text, "format" varchar not null default ('single-elimination'), "bracket_type" varchar not null default ('standard'), "registration_enabled" tinyint(1) not null default ('1'), "waiting_list_enabled" tinyint(1) not null default ('0'), "created_at" datetime, "updated_at" datetime, "approval_status" varchar check ("approval_status" in ('pending', 'approved', 'rejected')) not null default 'pending', "rejection_reason" text, "approved_by" integer, "approved_at" datetime, foreign key("organiser_id") references users("id") on delete cascade on update no action, foreign key("game_type_id") references game_types("id") on delete cascade on update no action, foreign key("approved_by") references "users"("id") on delete set null);
CREATE INDEX "tournaments_game_type_id_status_index" on "tournaments" ("game_type_id", "status");
CREATE INDEX "tournaments_is_featured_index" on "tournaments" ("is_featured");
CREATE INDEX "tournaments_organiser_id_index" on "tournaments" ("organiser_id");
CREATE INDEX "tournaments_status_starts_at_index" on "tournaments" ("status", "starts_at");
CREATE TABLE IF NOT EXISTS "conversations" ("id" integer primary key autoincrement not null, "type" varchar check ("type" in ('direct', 'group', 'tournament', 'community')) not null, "name" varchar, "context_id" integer, "last_message_id" integer, "created_at" datetime, "updated_at" datetime);
CREATE INDEX "conversations_type_context_id_index" on "conversations" ("type", "context_id");
CREATE TABLE IF NOT EXISTS "messages" ("id" integer primary key autoincrement not null, "conversation_id" integer not null, "user_id" integer not null, "content" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("conversation_id") references "conversations"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE INDEX "messages_conversation_id_created_at_index" on "messages" ("conversation_id", "created_at");
CREATE TABLE IF NOT EXISTS "conversation_participants" ("id" integer primary key autoincrement not null, "conversation_id" integer not null, "user_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("conversation_id") references "conversations"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE UNIQUE INDEX "conversation_participants_conversation_id_user_id_unique" on "conversation_participants" ("conversation_id", "user_id");
CREATE TABLE IF NOT EXISTS "typing_indicators" ("id" integer primary key autoincrement not null, "user_id" integer not null, "context_id" integer not null, "context_type" varchar not null default 'conversation', "started_at" datetime not null, "expires_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE UNIQUE INDEX "typing_indicators_user_id_context_id_context_type_unique" on "typing_indicators" ("user_id", "context_id", "context_type");
CREATE TABLE IF NOT EXISTS "user_skill_levels" ("id" integer primary key autoincrement not null, "user_id" integer not null, "game_type_id" integer not null, "skill_level" varchar check ("skill_level" in ('beginner', 'intermediate', 'advanced', 'expert')) not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("game_type_id") references "game_types"("id") on delete cascade);
CREATE UNIQUE INDEX "user_skill_levels_user_id_game_type_id_unique" on "user_skill_levels" ("user_id", "game_type_id");
CREATE TABLE IF NOT EXISTS "user_preferred_facilities" ("id" integer primary key autoincrement not null, "user_id" integer not null, "facility_id" varchar not null, "facility_name" varchar not null, "facility_address" varchar, "latitude" numeric, "longitude" numeric, "membership_type" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE UNIQUE INDEX "user_preferred_facilities_user_id_facility_id_unique" on "user_preferred_facilities" ("user_id", "facility_id");
CREATE TABLE IF NOT EXISTS "oauth_personal_access_clients" ("id" integer primary key autoincrement not null, "client_id" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE INDEX discussions_game_event_id_index ON discussions(game_event_id);
